INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-exam-linear-algebra-set-06-s1-4', 'exam-linear-algebra-set-06', 'exam-linear-algebra-set-06-sec-1', 2, '若线性方程组有解，则常数应满足', '若线性方程组 $\\left\\{\\begin{aligned}x_{1}+x_{2}&=-a_{1}\\\\ x_{2}+x_{3}&=a_{2}\\\\ x_{3}+x_{4}&=-a_{3}\\\\ x_{4}+x_{1}&=a_{4}\\end{aligned}\\right.$ 有解，则常数 $a_{1},a_{2},a_{3},a_{4}$ 应满足条件 \\_\\_\\_\\_', '[""]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 2, '[]'::jsonb, '长理线代期末试卷汇总-第06套', 4) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
